script:
ship_event = {
	id = defense_platform_policy.1
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		owner = {
			OR = {
				has_policy_flag = defense_platform_resilient_frames
				has_policy_flag = defense_platform_reinforced_plating
			}
		}
	}

	immediate = {
		if = {
			limit = {
				is_defense_platform_ship = yes
				owner = { has_policy_flag = defense_platform_resilient_frames }
			}
			set_disable_at_health = 0.05
		}
		if = {
			limit = {
				owner = { has_policy_flag = defense_platform_reinforced_plating }
				fleet = { is_defense_platform_fleet = yes }
			}
			fleet = {
				if = {
					limit = { NOT = { has_modifier = defense_platform_reinforced_field } }
					add_modifier = {
						modifier = defense_platform_reinforced_field
					}
				}
			}
		}
	}
}

