ship_event = {
	id = defense_platform_policy.5
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		fleet = {
			# Reinforced Plating field should match the new owner's doctrine; never sits on a waystation
			if = {
				limit = {
					is_defense_platform_fleet = yes
					owner = { has_policy_flag = defense_platform_reinforced_plating }
					NOT = { has_modifier = defense_platform_reinforced_field }
				}
				add_modifier = { modifier = defense_platform_reinforced_field }
			}
			else_if = {
				limit = {
					has_modifier = defense_platform_reinforced_field
					OR = {
						NOT = { is_defense_platform_fleet = yes }
						NOT = { owner = { has_policy_flag = defense_platform_reinforced_plating } }
					}
				}
				remove_modifier = defense_platform_reinforced_field
			}
			# Resilient Frames disable state should match the new owner on any inherited platforms
			every_owned_ship = {
				limit = { is_defense_platform_ship = yes }
				if = {
					limit = { owner = { has_policy_flag = defense_platform_resilient_frames } }
					set_disable_at_health = 0.05
				}
				else = {
					set_disable_at_health = no
					if = {
						limit = { is_disabled = yes }
						repair_percentage = 0.45 # recover a platform left disabled by the previous owner
						set_disabled = no
					}
				}
			}
		}
	}
}
